        $rows=accounting_read($pdo,function()use($pdo,$uid,$jid){reporting_actor($pdo,$uid,['Admin']);$s=$pdo->prepare("SELECT l.id,l.account_id,l.debit_amount,l.credit_amount,c.Name account_name,j.entry_date,j.description FROM journal_entry_lines l JOIN journal_entries j ON j.id=l.journal_entry_id JOIN Categories c ON c.CategoryID=l.account_id WHERE j.id=? AND j.status='posted' ORDER BY l.id LIMIT 501");$s->execute([$jid]);$rows=$s->fetchAll(PDO::FETCH_ASSOC);if(!$rows)throw new ReportingProblem('That recorded transaction was not found.',404);if(count($rows)>500)throw new ReportingProblem('This transaction needs a narrower setup review.',422);return $rows;});header('Content-Type: application/json; charset=utf-8');echo json_encode(['ok'=>true,'data'=>$rows]);exit;
    }
}catch(ReportingProblem $e){$status=$e->status;$error=$e->getMessage();}catch(Throwable $e){$status=503;$error='Reporting setup could not be loaded. Please try again.';error_log('Report setup read unavailable.');}
http_response_code($status);if(($_GET['format']??'')==='lines'){header('Content-Type: application/json; charset=utf-8');echo json_encode(['ok'=>false,'error'=>$error]);exit;}if(in_array($status,[401,403,405],true))exit($esc($error));
