<form id="rs-form"><fieldset id="rs-fields"<?= $published?' disabled':'' ?>><section class="fr-sheet"><h2>1. Reporting period</h2><div class="fr-controls"><label>Setup effective from<input type="month" id="rs-effective" required value="<?= $esc(substr($payload['effective_from'],0,7)) ?>"></label><label>Reporting year starts in<select id="rs-year"><?php for($i=1;$i<=12;$i++): ?><option value="<?= $i ?>"<?= (int)$payload['year_start_month']===$i?' selected':'' ?>><?= $esc(DateTimeImmutable::createFromFormat('!m',(string)$i)->format('F')) ?></option><?php endfor; ?></select></label></div><p class="fr-help">January is the initial convention. Confirm the organization's reporting year; account balances always follow their actual dates.</p></section>
